        bio.clutchShells = Array.from({ length: count }, () => SHELL_TRAITS[Math.floor(rng() * SHELL_TRAITS.length)]);
        bio.clutchGenders = Array.from({ length: count }, () => (rng() < 0.5 ? 'female' : 'male'));
        logEvent(state, `${entity.role}: clutch fertilized`);
