    const profile = COMP_ARCHETYPE_PROFILES[archetype] || COMP_ARCHETYPE_PROFILES.familiar_fox;

    const ageDays = Math.round(compClamp(Math.trunc(compFiniteOr(src.ageDays, 0)), 0, 36_500));
